];

const allData = [];

for (const w of weekends) {
  const url = `https://book.arlohotels.com/?adult=2&arrive=${w.arrive}&chain=19470&child=0&depart=${w.depart}&level=chain&locale=en-US&rooms=1`;
  console.log(`Loading ${w.name}...`);
  await tool.navigate({ tabId, url });

  // Wait until "results available" or "VIEW RATES" or "No rooms available" appears
  await tool.wait_for({ tabId, condition: "text_visible", value: "results available", timeout_ms: 12000 });

  const extracted = await browserjs(tabId, () => {
    const nycHotels = ["Arlo Williamsburg", "Arlo Midtown", "Arlo NoMad", "Arlo SoHo"];
    const out = {};

    // Find all h2s
    const h2s = Array.from(document.querySelectorAll('h2'));
    for (const h of h2s) {
      const name = h.innerText.trim();
      if (nycHotels.includes(name)) {
        let container = h.closest('div');
        while (container && !container.innerText.includes('VIEW RATES') && !container.innerText.includes('No rooms available')) {
          if (!container.parentElement) break;
          container = container.parentElement;
        }
        const text = container ? container.innerText : h.parentElement.innerText;
        const priceMatch = text.match(/From\s*\$([0-9,]+)/i);
        out[name] = {
          pricePerNight: priceMatch ? parseInt(priceMatch[1].replace(/,/g, ''), 10) : null,
          available: !text.includes('No rooms available') && !!priceMatch,
          snippet: text.split('\n').filter(Boolean).slice(0, 6).join(' | ')
        };
      }
    }
    return out;
  });

  console.log(`Data for ${w.name}:`, JSON.stringify(extracted, null, 2));
  allData.push({
