    const inputs = Array.from(document.querySelectorAll('input')).filter(i => i.placeholder === 'MM/DD/YYYY');
    if (inputs.length >= 2) {
      const setVal = (input, val) => {
        input.focus();
        input.value = val;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
      };
      setVal(inputs[0], start);
      setVal(inputs[1], end);
      const applyBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText?.trim() === 'Apply' && b.offsetParent !== null);
      if (applyBtn) {
        applyBtn.click();
        return true;
      }
    }
    return false;
  }, m.start, m.end);

  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

  const resultCount = await browserjs(tabId, () => {
    const text = document.body.innerText;
    const match = text.match(/ALL EVENTS IN NEW YORK CITY\s*([0-9,]+)\s*RESULTS/i);
    return match ? match[1] : (text.includes("0 RESULTS") ? "0" : "unknown");
  });

  console.log(`${m.name}: ${resultCount} results`);
}

