const tabId = 2136412445;

const setMayDates = await browserjs(tabId, () => {
  const dateInputs = Array.from(document.querySelectorAll('input')).filter(i => i.placeholder === 'MM/DD/YYYY');
  if (dateInputs.length >= 2) {
    // Set native value
    const setVal = (input, val) => {
      input.focus();
      input.value = val;
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.dispatchEvent(new Event('change', { bubbles: true }));
    };
    setVal(dateInputs[0], '05/01/2027');
    setVal(dateInputs[1], '05/31/2027');

    // Find Apply button in the modal
    const applyBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText?.trim() === 'Apply' && b.offsetParent !== null);
    if (applyBtn) {
      applyBtn.click();
      return { applied: true, from: dateInputs[0].value, to: dateInputs[1].value };
    }
    return { applied: false, reason: "No visible apply button" };
  }
  return { applied: false, reason: "Date inputs not found" };
});

console.log("Set May dates result:", setMayDates);
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });

