const tabId = 2136412445;

const allDates = await browserjs(tabId, () => {
  // Let's get all dates and event names from the list
  const items = Array.from(document.querySelectorAll('[data-testid*="event"], [class*="EventItem"], tr, li')).map(el => {
    const text = el.innerText?.trim();
    if (!text) return null;
    const link = el.querySelector('a[href*="/event/"]')?.href;
    return { text, link };
  }).filter(Boolean);

  // Or let's just search the whole text of the page for months
  const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  const text = document.body.innerText;
  const foundMonths = months.filter(m => text.includes(m));

  // Also look for 2027
  const has2027 = text.includes("2027");

  // Let's find the last date listed on the page
  const dateMatches = text.match(/[A-Z][a-z]+ \d{1,2}, \d{4}/g) || [];

  return {
    itemsCount: items.length,
    foundMonths,
    has2027,
    sampleDateMatches: Array.from(new Set(dateMatches)).slice(0, 20),
    lastDates: Array.from(new Set(dateMatches)).slice(-10)
  };
});

console.log("All dates on Yankees page:", JSON.stringify(allDates, null, 2));

