const tabId = 2136412445;

const sportsSectionInfo = await browserjs(tabId, () => {
  // Find "POPULAR SPORTS IN NEW YORK CITY" section
  const headers = Array.from(document.querySelectorAll('h2, h3'));
  const sportsH2 = headers.find(h => h.innerText?.includes('POPULAR SPORTS') || h.innerText?.includes('NYC SPORTS TEAMS'));

  // Find all sports events or team links
  const sportsTeamLinks = [];
  if (sportsH2) {
    let container = sportsH2.parentElement;
    for (let i = 0; i < 4; i++) {
      if (!container) break;
      const links = Array.from(container.querySelectorAll('a')).map(a => ({
        text: a.innerText?.trim(),
        href: a.href
      })).filter(x => x.text);
      if (links.length > 2) {
        sportsTeamLinks.push(...links);
        break;
      }
      container = container.parentElement;
    }
  }

  // Also let's check date button and category button
  const dateBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText?.includes('Change date range'));

  return {
    sportsTeamLinks: sportsTeamLinks.slice(0, 15),
    hasDateBtn: !!dateBtn
  };
});

console.log("Sports section info:", JSON.stringify(sportsSectionInfo, null, 2));

