const tabId = 2136412445;

const filterMay = await browserjs(tabId, () => {
  const inputs = Array.from(document.querySelectorAll('input')).filter(i => i.placeholder === 'MM/DD/YYYY');
  if (inputs.length >= 2) {
    const setVal = (input, val) => {
      input.focus();
      input.value = val;
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.dispatchEvent(new Event('change', { bubbles: true }));
    };
    setVal(inputs[0], '04/30/2027');
    setVal(inputs[1], '05/31/2027');

    const applyBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText?.trim() === 'Apply' && b.offsetParent !== null);
    if (applyBtn) {
      applyBtn.click();
      return { applied: true, start: inputs[0].value, end: inputs[1].value };
    }
    return { applied: false, reason: "No visible apply button" };
  }
  return { applied: false, reason: "Inputs not found" };
});

console.log("Filter May result:", filterMay);
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 5000 });

const pageStateAfterMay = await browserjs(tabId, () => {
  const text = document.body.innerText;
  const links = Array.from(document.querySelectorAll('a[href*="/event/"]')).map(a => ({
    text: a.innerText?.trim(),
    href: a.href,
    parentText: a.closest('div, li')?.innerText
  }));

  // Look for any mention of events or "no events found"
  const noEvents = text.includes("No events found") || text.includes("No results") || text.includes("0 RESULTS");

  return {
    title: document.title,
    url: window.location.href,
    linksCount: links.length,
    noEvents,
    sampleLinks: links.slice(0, 15),
    bodySnippet: text.slice(0, 1200)
  };
});

console.log("Page state after May filter:", JSON.stringify(pageStateAfterMay, null, 2));

